  /* ───────── 定稿时改过的牌：编号、牌名、牌值都不动 ─────────
     why：rule = 规则换了（没有进度条了）· gone = 原来点的「英联邦」没有了，重写 · name = 只是换成新的大区名或新的说法
     牌面上不再说「芯片链」：要点那四个市场，就直接写台湾、韩国、日本、荷兰。
     「东南亚」「欧洲」还是大区名，不用改。 */
  function rewrite(id, why, text, note) {
    cards.forEach(function (x) {
      if (x.id !== id) return;
      x.was = x.text; x.text = text; x.rev = why;
      if (note) x.note = note;
    });
  }
